def task_func(directory, extensions=[".txt", ".docx", ".xlsx", ".csv"], keep_zero=True):
    if not os.path.isdir(directory):
        raise OSError(f"Directory '{directory}' does not exist.")

    file_counts = Counter()
    for ext in extensions:
        pattern = f"{ext}/*"
        for filename in glob.glob(os.path.join(directory, pattern), recursive=True):
            file_counts[os.path.splitext(filename)[1]] += 1

