import hashlib

def task_func(path, delimiter):
    components = []
    for comp in re.split(delimiter, path):
        try:
            # Check if the component is a file
            statinfo = os.stat(comp)
            if statinfo.st_size > 0:  # File size greater than zero indicates it exists as a file
                components.append((comp, hashlib.md5(open(comp, 'rb').read()).hexdigest()))
            else:
                components.append((comp, None))
        except FileNotFoundError:
            components.append((comp, None))  # Handle missing files gracefully
    return components

