def task_func(directory):
    # Find all lines containing only digits
    nums = [x for x in os.listdir(directory) if re.match(r'\d+', x)]

    # Create directories for each number
    dirs = {int(x): [] for x in set(nums)}

    # Move files into corresponding directories
    for f in os.listdir(directory):
        if f.endswith('.txt'):
            num = int(re.search(r'\d+', f).group())
            dirs[num].append(f)

    # Organize files by moving them to their respective directories
    for k, v in dirs.items():
        new_dir = os.path.join(directory, 'dir_' + str(k))
        try:
            os.makedirs(new_dir)
        except FileExistsError:
            pass
        for i in v:
            shutil.move(os.path.join(directory, i), os.path.join(new_dir, i))

    return (directory, dirs)

