import os
import shutil

def task_func(path, delimiter="/"):
    if not isinstance(path, str) or not path.strip():
        raise ValueError("Invalid path")

    try:
        dir_list = path.split(delimiter)
    except AttributeError:
        raise FileNotFoundError(f"File '{path}' not found")

    total_disk_usage = sum(os.path.getsize(dir_path) for dir_path in dir_list)
    used_disk_usage = shutil.disk_usage(dir_list[0]).used / (1024 ** 3)

    return [(dir_name, {"total": total_disk_usage, "used": used_disk_usage, "free": total_disk_usage - used_disk_usage}) 
            for dir_name in dir_list]

